package com.example.hexagon.core.port.outbound;

import com.example.hexagon.core.domain.User;
import java.util.Optional;
import java.util.UUID;

// Driven Port (Outbound Port) defined purely in the domain core
public interface SaveUserPort {
    User save(User user);
    Optional<User> findById(UUID id);
}

package com.example.hexagon.infrastructure.adapter.persistence;

import com.example.hexagon.core.domain.User;
import com.example.hexagon.core.port.outbound.SaveUserPort;
import org.springframework.stereotype.Repository;
import java.util.Optional;
import java.util.UUID;

// Driven Adapter (Outbound Adapter) implementing the port using Spring Data / JPA
@Repository
public class SpringDataJpaUserAdapter implements SaveUserPort {

    private final SpringDataJpaRepository repository;

    public SpringDataJpaUserAdapter(SpringDataJpaRepository repository) {
        this.repository = repository;
    }

    @Override
    public User save(User user) {
        UserEntity entity = UserEntity.fromDomain(user);
        UserEntity saved = repository.save(entity);
        return saved.toDomain();
    }

    @Override
    public Optional<User> findById(UUID id) {
        return repository.findById(id).map(UserEntity::toDomain);
    }
}
